using Microsoft.EntityFrameworkCore;
namespace StudentHousing.Api;
public enum Role { Tenant, Landlord, Admin }
public enum PropertyStatus { Pending, Active, Rejected, Rented }
public enum RequestStatus { Pending, Approved, Rejected, Cancelled }
public class User { public Guid Id {get;set;}=Guid.NewGuid(); public string FullName {get;set;}=""; public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public string? PhoneNumber {get;set;} public Role Role {get;set;} public bool IsActive {get;set;}=true; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public List<Property> Properties {get;set;}=[]; }
public class Property { public int Id {get;set;} public Guid LandlordId {get;set;} public User Landlord {get;set;}=null!; public string Title {get;set;}=""; public string Description {get;set;}=""; public string Address {get;set;}=""; public string District {get;set;}=""; public string Ward {get;set;}=""; public decimal Price {get;set;} public decimal Area {get;set;} public PropertyStatus Status {get;set;}=PropertyStatus.Pending; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public DateTime UpdatedAt {get;set;}=DateTime.UtcNow; public List<PropertyImage> Images {get;set;}=[]; public List<PropertyAmenity> PropertyAmenities {get;set;}=[]; }
public class PropertyImage { public int Id {get;set;} public int PropertyId {get;set;} public Property Property {get;set;}=null!; public string ImageUrl {get;set;}=""; public string CloudinaryPublicId {get;set;}=""; public bool IsPrimary {get;set;} public int DisplayOrder {get;set;} }
public class Amenity { public int Id {get;set;} public string Name {get;set;}=""; public string Icon {get;set;}=""; public List<PropertyAmenity> PropertyAmenities {get;set;}=[]; }
public class PropertyAmenity { public int PropertyId {get;set;} public Property Property {get;set;}=null!; public int AmenityId {get;set;} public Amenity Amenity {get;set;}=null!; }
public class Favorite { public Guid UserId {get;set;} public User User {get;set;}=null!; public int PropertyId {get;set;} public Property Property {get;set;}=null!; }
public class ViewingRequest { public int Id {get;set;} public Guid TenantId {get;set;} public User Tenant {get;set;}=null!; public int PropertyId {get;set;} public Property Property {get;set;}=null!; public DateTime RequestedAt {get;set;} public string? Note {get;set;} public RequestStatus Status {get;set;}=RequestStatus.Pending; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public DateTime UpdatedAt {get;set;}=DateTime.UtcNow; }
public class HousingDb(DbContextOptions<HousingDb> options):DbContext(options) { public DbSet<User> Users=>Set<User>(); public DbSet<Property> Properties=>Set<Property>(); public DbSet<PropertyImage> PropertyImages=>Set<PropertyImage>(); public DbSet<Amenity> Amenities=>Set<Amenity>(); public DbSet<PropertyAmenity> PropertyAmenities=>Set<PropertyAmenity>(); public DbSet<Favorite> Favorites=>Set<Favorite>(); public DbSet<ViewingRequest> ViewingRequests=>Set<ViewingRequest>(); protected override void OnModelCreating(ModelBuilder b){ b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<Property>().Property(x=>x.Price).HasPrecision(18,2); b.Entity<Property>().Property(x=>x.Area).HasPrecision(10,2); b.Entity<Property>().ToTable(t=>{t.HasCheckConstraint("CK_Price","[Price] > 0");t.HasCheckConstraint("CK_Area","[Area] > 0");}); b.Entity<Property>().HasIndex(x=>new{x.Status,x.District,x.Price,x.Area,x.CreatedAt}); b.Entity<Amenity>().HasIndex(x=>x.Name).IsUnique(); b.Entity<PropertyAmenity>().HasKey(x=>new{x.PropertyId,x.AmenityId}); b.Entity<Favorite>().HasKey(x=>new{x.UserId,x.PropertyId}); b.Entity<ViewingRequest>().HasIndex(x=>new{x.TenantId,x.PropertyId,x.RequestedAt}); b.Entity<Property>().HasOne(x=>x.Landlord).WithMany(x=>x.Properties).HasForeignKey(x=>x.LandlordId).OnDelete(DeleteBehavior.Restrict); b.Entity<PropertyImage>().HasOne(x=>x.Property).WithMany(x=>x.Images).OnDelete(DeleteBehavior.Restrict); b.Entity<PropertyAmenity>().HasOne(x=>x.Property).WithMany(x=>x.PropertyAmenities).OnDelete(DeleteBehavior.Restrict); b.Entity<Favorite>().HasOne(x=>x.User).WithMany().OnDelete(DeleteBehavior.Restrict); b.Entity<Favorite>().HasOne(x=>x.Property).WithMany().OnDelete(DeleteBehavior.Restrict); b.Entity<ViewingRequest>().HasOne(x=>x.Tenant).WithMany().OnDelete(DeleteBehavior.Restrict); b.Entity<ViewingRequest>().HasOne(x=>x.Property).WithMany().OnDelete(DeleteBehavior.Restrict); b.Entity<Amenity>().HasData(new Amenity{Id=1,Name="Wi-Fi",Icon="wifi"},new Amenity{Id=2,Name="Máy lạnh",Icon="air-vent"},new Amenity{Id=3,Name="Bãi xe",Icon="bike"},new Amenity{Id=4,Name="Gác lửng",Icon="layers"}); }}
